Gordic.Previews.register("uct:Doklad", {
    // Ověřování, zda je řádek kompletní
    canRender: function (dto) { return dto.ixp != null; },
    // Samotné vykreslení náhledu
    render: function (div, dto) {
        if (dto.c === null)
            dto.c = new Decimal(0);
        if (dto.c0 === null)
            dto.c0 = new Decimal(0);
        if (dto.c1 === null)
            dto.c1 = new Decimal(0);
        //sumaUhrazeno = parseDecimal(dto.c_celk_mena).minus(parseDecimal(dto.c_zust_mena)).minus(parseDecimal(dto.c_dor));                       // výpočet uhrazené částky
        //sumaZauctovano = parseDecimal(dto.c_kzauc).minus(parseDecimal(dto.c_dor));                                                              // výpočet zaúčtované částky
        var currentElement = $(div);
        // data jsou ready -> samotné vytvoření náhledu
        currentElement.empty().append("<h2 class='g-state-text g-state-active' style='margin: 0.5rem;'>Doklad UCT " + dto.ixp + "</h2><hr style='margin: 0.5rem; opacity: 0.2;'/>");
        Gordic.Previews.displayLinkButton(div, dto);
        var tmp = $.newDiv("gform--view-mode").appendTo(currentElement)
            .gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" }).
            //gformsection("create").gpidbar({ pid: dto.ixp as any }).
            gformsection("create").
            gformrow("addFieldsRow", "jres:30250673").gformtext(dto.dat_evid == null ? "" : Gordic.Templates.Formatters.date(parseDate(dto.dat_evid)), "bold") //RC 30250673 : Datum evidence
            .gformrow("addFieldsRow", "jres:30250297").gformtext(dto.rok === null ? "" : Gordic.Templates.Formatters.date(new Date(dto.rok, dto.mesic, dto.den)), "bold") //RC 30250297 : Datum účtování
        ;
        if (dto.rok_dph !== null && typeof dto.rok_dph !== undefined) {
            tmp.gformrow("addFieldsRow", "jres:30250299").gformtext(dto.rok_dph.toString(), "bold") //RC 30250299 : Rok DPH
                .gformrow("addFieldsRow", "jres:30250300").gformtext(dto.mesic_dph.toString(), "bold") //RC 30250300 : Měsíc DPH
            ;
        }
        tmp.gformrow("addFieldsRow", "jres:30250184").gformtext(dto.ac_ixe, "bold") //RC 30250184 : Doklad
            .gformrow("addFieldsRow", "jres:30250672").gformtext(dto.ac_ag, "bold") //RC 30250672 : Agendové číslo
            .gformrow("addFieldsRow", "jres:30250587").gformtext(dto.ac, "bold") //RC 30250587 : Evidenční číslo
            .gformrow("addFieldsRow", "jres:30250093").gformtext("<b class='g-state-text g-state-info'>" + dto.ktgTypNazev + "</b>", "bold") //RC 30250093 : Typ dokladu
            //gformrow("addFieldsRow", "jres:29750112").gformtext("<b class='g-state-text g-state-success'>" + (dto.ps_sml != null && dto.ps_sml != "" && dto.ps_sml != undefined ? dto.ps_sml : "----") + "</b>", "bold"). // RC 29750112 : Smlouva/objednávka
            .gformrow("addFieldsRow", "jres:30250094").gformtext("" + (dto.drd === null ? "" : dto.drd), "bold") //RC 30250094 : Druh dokladu
            .gformsection("create")
            .gformrow("addFieldsRow", "jres:30250092").gformtext("<b class='g-state-text g-state-info'>" + dto.stav_txt + "</b>", "bold") // RC 29750113 : Stav dokladu //RC 30250092 : Stav dokladu
            .gformsection("create")
            .gformrow("addFieldsRow", "jres:30250294").gformtext(Gordic.Templates.Formatters.number(parseDecimal(dto.c), "C") + " CZK") //RC 30250294 : Částka na hlavičce
            .gformrow("addFieldsRow", "jres:30250295").gformtext(Gordic.Templates.Formatters.number(parseDecimal(dto.c0 === null || typeof dto.c0 === "undefined" ? 0 : dto.c0), "C") + " CZK") //RC 30250295 : Suma MD 
            .gformrow("addFieldsRow", "jres:30250296").gformtext(Gordic.Templates.Formatters.number(parseDecimal(dto.c1 === null || typeof dto.c1 === "undefined" ? 0 : dto.c1), "C") + " CZK") //RC 30250296 : Suma Dal
            //gformrow("addFieldsRow", "jres:29750118").gformtext(Gordic.Templates.Formatters.number(sumaZauctovano.toNumber(), "C") + " CZK").   // RC 29750118 : Zaúčtováno v CZK
            .gformrow("addFieldsRow", "jres:30250023").gformtext(dto.ixs_fun_nazev, "bold") //RC 30250023 : Zpracovatel
            .gformsection("create")
            .gformrow("addFieldsRow", "jres:30250024").gformtext(dto.popis, "bold"); // RC 29750071 : Popis //RC 30250024 : Popis
        currentElement.resize().find(".gform-section").children("label").first().addClass("g-state-text g-state-error");
    }
});
